package com.sun.fortress.runtimeSystem;

import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.ForkJoinTask;
import java.util.concurrent.RecursiveAction;

import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;

import static com.sun.fortress.runtimeSystem.FortressExecutable.numThreads;
import static com.sun.fortress.runtimeSystem.FortressExecutable.spawnThreshold;

import com.sun.fortress.useful.MagicNumbers;

/** Base class for Fortress tasks.  Includes administrative methods
 *  that make code generation for task spawn a bit easier.
 *
 *  We shy away from the "easiest thing of all": forking in the constructor.
 *  Given the plethora of final fields in the usual Fortress task, such a step
 *  would be a memory model disaster!  Instead, we generate code like:
 *    Fib$task0 tmp = new Fib$task0(arg);
 *    tmp.forkIfProfitable();
 *    ... other code ...
 *    tmp.joinOrRun();
 *    ... use tmp.result (compiler-inserted field) if desired ...
 */
public abstract class BaseTask extends FortressExecutable {
    // Could get this by hacking ForkJoinTask's status field, but
    // not touching that for now as it's too changeable
    private static final int UNFORKED = 0;
    private static final int FORKED = 1;
    private static final int EXECUTED = 2;
    private int actuallyForked = UNFORKED;

    BaseTask parent;
    Transaction transaction;
    private static Random gen = new Random();

    private static Boolean debug = false;

    private static void debug(String s) {
        if (debug)
            System.out.println("BaseTaskDebug: " + Thread.currentThread().getName() + ":" + s);
    }

    /** Each base task has a depth in the pedigree tree, the value of
    the next magic number, a unique gamma value that is the dot
    product of the task's pedigree and the magic numbers array, and a
    dot product that is the task's gamma value with extra magic added
    in for each random number the task generates **/

    private int depth;
    private long nextMagicNumber; 
    private long gamma; 
    private long dotProduct;

    // The constructor used by the primordial task.
    public BaseTask() {
        super();
        this.parent = null;
        this.transaction = null;

        // Pedigree information
        this.depth = 0;
        this.nextMagicNumber = 
            MagicNumbers.trulyRandomLongNumbers(this.depth + 1);
        this.gamma = 
            MagicNumbers.trulyRandomLongNumbers(this.depth);
        this.dotProduct = this.gamma;
    }

    public BaseTask(BaseTask parent) {
        super();
        this.parent = parent;
        this.transaction = parent.transaction;

        // Pedigree information
        this.depth = parent.getDepth() + 1;
        this.nextMagicNumber = 
            MagicNumbers.trulyRandomLongNumbers(this.depth + 1);
        this.gamma = parent.makeNewChild();
        this.dotProduct = this.gamma;
    }

    private int getDepth() {
        return this.depth;
    }

    /* Returns a unique gamma for a child task */
    public long makeNewChild() {
        this.gamma += this.nextMagicNumber;
        return this.gamma;
    }

    /* Records that a new random number has been asked for, and
     * returns the task's dotProduct */
    public long makeNewRandom() {
        this.dotProduct += this.nextMagicNumber;
        return dotProduct;
    }

    /* For a group of arms that completes abruptly: waits for this arm
     * where it was forked, and takes what it threw.  An arm that was never
     * forked is not run.  The current task is saved and restored around the
     * join, as joinOrRun does. */
    public final void joinIfForked() {
        if (actuallyForked == UNFORKED) return;
        Thread thread = Thread.currentThread();
        if (thread instanceof FortressTaskRunner) {
            FortressTaskRunner ftr = (FortressTaskRunner) thread;
            BaseTask saved = ftr.task();
            try {
                this.quietlyJoin();
            } finally {
                ftr.setTask(saved);
            }
        } else {
            this.quietlyJoin();
        }
    }

    private static boolean unsafeWorthSpawning() {
        return (numThreads > 1 &&
                (spawnThreshold < 0 || getSurplusQueuedTaskCount() <= spawnThreshold));
    }

    public static boolean worthSpawning() {
        return numThreads > 1 && !ForkJoinTask.inForkJoinPool() || unsafeWorthSpawning();
    }

    // Corner case: we attempted to spawn work from a class
    // initializer.  That doesn't work as the initializer isn't run in
    // a ForkJoinWorkerThread.  So we must submit the task to the
    // global task pool instead.
    private final void executeAlways() {
        FortressExecutable.group.execute(this);
        actuallyForked = EXECUTED;
    }

    private final void forkAlways() {
        this.fork();
        actuallyForked = FORKED;
    }

    public final void forkIfProfitable() {
        if (ForkJoinTask.inForkJoinPool()) {
            if (unsafeWorthSpawning()) {
                this.forkAlways();
            }
        } else {
            this.executeAlways();
        }
    }

    public final void joinOrRun() {
        // Emphasize common UNFORKED case.
        if (actuallyForked == UNFORKED) {
            this.compute();
        } else {
            // java.util.concurrent has no helpJoin(); its join() already
            // helps by running queued subtasks when called from a worker
            // thread, so FORTRESS_HELP_JOIN (useHelpJoin) is now a no-op.
            //
            // That helping breaks an invariant jsr166y's blocking join
            // preserved: generated compute() bodies point the worker's
            // current-task field at themselves (BaseTask.setTask) and never
            // restore it, and the transaction statics below resolve the
            // current transaction through that field.  A task run on this
            // thread while join() helps leaves the field pointing at an
            // unrelated task, corrupting transaction state in the joiner's
            // continuation.  Save and restore the field across join(),
            // mirroring Evaluator's setCurrentTask(currentTask) after
            // TupleTask.invokeAll on the interpreter side.
            Thread thread = Thread.currentThread();
            if (thread instanceof FortressTaskRunner) {
                FortressTaskRunner ftr = (FortressTaskRunner) thread;
                BaseTask saved = ftr.task();
                try {
                    this.join();
                } finally {
                    ftr.setTask(saved);
                }
            } else {
                this.join();
            }
        }
    }

   public static void startTransaction() {
        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
        BaseTask currentTask = ftr.getTask();
        if (debug) debug("startTransaction: ftr = " + ftr + " current task = " + currentTask);

        Transaction transaction = Transaction.TXBegin(currentTask.transaction());
        if (debug) debug("Start transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction);
        currentTask.setTransaction(transaction);
    }

    public static void endTransaction() {
        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
        BaseTask currentTask = ftr.getTask();
        if (debug) debug("endTransaction: ftr = " + ftr + " current task = " + currentTask);
        Transaction transaction = ftr.getTask().transaction();
        if (debug) debug("End transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction);
        if (transaction != null) {
            transaction.TXCommit();
            currentTask.setTransaction(transaction.getParent());
        }
        ftr.recordEndTransaction();
    }

    public static void delayTransaction() {
        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
        long startTime = System.nanoTime();
        long elapsedTime = System.nanoTime() - startTime;

        if (useExponentialBackoff) {
            double r = gen.nextDouble() + 0.5; // Random number between 0.5 and 1.5
            long waitNanoseconds = (long) ((1L << (ftr.getRetries() + machineConstant)) * r);

            while (elapsedTime < waitNanoseconds) {
                elapsedTime = System.nanoTime() - startTime;
            }
        }

        ftr.incElapsedTime(elapsedTime);
        ftr.incRetries();
    }

    public static Transaction getCurrentTransaction() {
        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
        if (debug) debug("getCurrentTransaction: ftr = " + ftr );
        if (ftr.getTask() != null)
            return ftr.getTask().transaction();
        else return null;
    }

    public static BaseTask getCurrentTask() {
        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
        if (debug) debug("getCurrentTask: ftr = " + ftr );
        return ftr.getTask();
    }

    public static boolean inATransaction() {
        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
        if (debug) debug("inATransaction: ftr = " + ftr + " task = " + ftr.getTask());

        if (ftr.getTask() != null) 
            if (ftr.getTask().transaction() != null)
                return true;
        return false;
    }

    public static void setTask(BaseTask t) {
        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
        if (debug) debug("setTask: ftr = " + ftr + " task = " + t);
        ftr.setTask(t);
    }

    Transaction transaction() {
        return transaction;
    }

    public void setTransaction(Transaction t) {
        transaction = t;
    }    

    public void printStatistics() {
        FortressTaskRunnerGroup ftrg = (FortressTaskRunnerGroup) getPool();
        ftrg.printStatistics();
    }

    /**
     * The handler of a compiled atomic block, with whatever its body or its commit threw.  It ends
     * the block's transaction, whose writes go with it.  It returns for an abort of that transaction,
     * and the block starts again: an abort that names it, the abort() of a program, which names none
     * and is taken by the innermost block, or any abort that reaches the outermost block.  It throws
     * on an abort that names an ancestor, whose block starts again, and any other exception, which
     * leaves the block; a nested transaction first hands the reads on which that exception was thrown
     * to its parent (Transaction.TXLeave).
     */
    public static void leaveTransaction(Throwable t) {
        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
        BaseTask currentTask = ftr.getTask();
        Transaction transaction = currentTask.transaction();
        if (debug) debug("Leave transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction + " on " + t);
        if (transaction == null)
            BaseTask.<RuntimeException>throwOn(t);
        currentTask.setTransaction(transaction.getParent());
        if (!(t instanceof TransactionAbortException)) {
            try {
                transaction.TXLeave();
            } catch (TransactionAbortException stale) {
                t = stale;
            }
        }
        if (t instanceof TransactionAbortException) {
            Transaction named = ((TransactionAbortException) t).transaction();
            if (named == null || named == transaction || transaction.getParent() == null)
                return;
        }
        BaseTask.<RuntimeException>throwOn(t);
    }

    /** Throws t as it is, checked or not, as generated code throws. */
    @SuppressWarnings("unchecked")
    private static <T extends Throwable> void throwOn(Throwable t) throws T {
        throw (T) t;
    }
}

