    /*
     * label and exit (Specification/basic/expressions/label.tex, section
     * "Label and Exit").  An exit completes abruptly: it throws a LabelExit
     * that names the evaluation of the label block that it leaves, and the
     * block's handler takes the exits that name its own evaluation and throws
     * every other on.  The evaluation's identity is an immutable local of
     * the block under the label's name, which the checker lets no variable
     * in scope share; so a function expression or a task whose body exits
     * holds it as it holds any variable of the block, and an exit reaches
     * its label from a loop's body, through the library's code and from
     * another task.  A group of forked arms joins its arms before the exit
     * passes it (joinForkedArms), and no catch clause takes it, since it is
     * no FException.
     */
    private static final String LABEL_EXIT = "com/sun/fortress/runtimeSystem/LabelExit";
    private static final String LABEL_EXIT_TARGET = LABEL_EXIT + "$Target";

    public void forLabel(com.sun.fortress.nodes.Label x) {
        debug("forLabel ", x);
        Id name = x.getName();

        // The identity of this evaluation of the block.
        mv.visitTypeInsn(NEW, LABEL_EXIT_TARGET);
        mv.visitInsn(DUP);
        mv.visitMethodInsn(INVOKESPECIAL, LABEL_EXIT_TARGET, "<init>", "()V");
        VarCodeGen target =
            new VarCodeGen.LocalVar(name, NodeFactory.makeAnyType(NodeUtil.getSpan(name)), this);
        target.assignValue(mv);

        Label start = new Label();
        Label end = new Label();
        Label handler = new Label();
        Label done = new Label();

        // The label's name is in scope in the body only.
        CodeGen cg = new CodeGen(this);
        cg.addLocalVar(target);
        mv.visitLabel(start);
        x.getBody().accept(cg);
        mv.visitLabel(end);
        mv.visitJumpInsn(GOTO, done);

        // After the body's code, so that the entry of a label, a try or an
        // atomic block nested in the body comes first in the exception table.
        mv.visitTryCatchBlock(start, end, handler, LABEL_EXIT);

        // The exit's value is the block's, at the block's type.
        mv.visitLabel(handler);
        target.pushValue(mv);
        mv.visitMethodInsn(INVOKEVIRTUAL, LABEL_EXIT, "valueAt",
                           "(Ljava/lang/Object;)Ljava/lang/Object;");
        Option<Type> labelType = x.getInfo().getExprType();
        if (labelType.isNone())
            throw sayWhat(x, "Missing type information for a label block");
        if (!(labelType.unwrap() instanceof BottomType))
            InstantiatingClassloader.generalizedCastTo(mv,
                NamingCzar.jvmTypeDesc(labelType.unwrap(), thisApi(), false, true));

        mv.visitLabel(done);
        target.outOfScope(mv);
    }

    public void forExit(com.sun.fortress.nodes.Exit x) {
        debug("forExit ", x);
        // The disambiguator gives every exit its target.
        if (x.getTarget().isNone())
            throw sayWhat(x, "An exit without a target");
        VarCodeGen target = getLocalVarOrNull(x.getTarget().unwrap());
        if (target == null)
            throw sayWhat(x, "An exit whose label is not in scope");

        // The with value first, so that nothing of the exit is on the
        // operand stack while it is evaluated.
        if (x.getReturnExpr().isSome())
            x.getReturnExpr().unwrap().accept(this);
        else
            pushVoid();
        target.pushValue(mv);
        mv.visitMethodInsn(INVOKESTATIC, LABEL_EXIT, "of",
                           "(Ljava/lang/Object;Ljava/lang/Object;)L" + LABEL_EXIT + ";");
        mv.visitInsn(ATHROW);
    }

    public void defaultCase(Node x) {
        throw sayWhat(x);
    }

    public void forImportStar(ImportStar x) {
        // do nothing, don't think there is any code go generate
    }

    public void forAssignment(Assignment x) {
        List<Lhs> lhs_list = x.getLhs();
        if (lhs_list.size() != 1)
            throw new RuntimeException(" Can't do multiple assignments yet");
        Lhs lhs = lhs_list.get(0);
        if (! (lhs instanceof VarRef))
            throw new RuntimeException(" Can't do anything other than VarRefs");
        Option<FunctionalRef> assignOp = x.getAssignOp();
        if (assignOp.isSome())
            throw new RuntimeException(" Can't handle special assignments");

        List<CompoundAssignmentInfo> assignmentInfos = x.getAssignmentInfos();
        if (assignmentInfos.size() > 0)
            throw new RuntimeException(" Can't handle compound assigments");

        Expr rhs = x.getRhs();

        rhs.accept(this);
        VarRef vr = (VarRef) lhs;
        Id var = vr.getVarId();
        VarCodeGen r = getLocalVarOrNull(var);

        if (r != null)
            r.assignValue(this.mv);
        // All statements need to leave a value on the stack.
        pushVoid();
    }


    public void forBlockHelper(Block x) {
        boolean oldInABlock = inABlock;
        inABlock = true;
        debug("forBlock ", x);
        doStatements(x.getExprs());
        inABlock=oldInABlock;
    }

    /** The body of an atomic block and its commit, inside the transaction that forAtomicBlock began. */
    public void forAtomicBlockHelper(Block x) {
        forBlockHelper(x);
        mv.visitMethodInsn(INVOKESTATIC, "com/sun/fortress/runtimeSystem/BaseTask", 
                           "endTransaction", "()V");
    }

    // For debugging        
    public void printString(CodeGenMethodVisitor mv, String s) {
        mv.visitFieldInsn(Opcodes.GETSTATIC, "java/lang/System", "out", "Ljava/io/PrintStream;");
        mv.visitLdcInsn(s);
        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/io/PrintStream", "println", "(Ljava/lang/String;)V");
    }

    public void forAtomicBlock(Block x) {
        Label start = new Label();
        Label end = new Label();
        Label exit = new Label();
        Label handler = new Label();
        Label startOver = new Label();

        mv.visitLabel(startOver);
        mv.visitMethodInsn(INVOKESTATIC, 
                           "com/sun/fortress/runtimeSystem/BaseTask", 
                           "startTransaction", "()V");     
        mv.visitLabel(start);
        forAtomicBlockHelper(x);
        mv.visitLabel(end);
        mv.visitJumpInsn(GOTO, exit);

        // The JVM takes the first entry of the exception table that covers a throw, so the entry
        // is written after the body's code: the entry of an atomic block or a try nested in the
        // body is then before this one.  The entry takes every exception.
        mv.visitTryCatchBlock(start, end, handler, null);

        // Exception Handler: the transaction ends.  leaveTransaction returns for an abort of
        // this block's own transaction, and throws on what leaves the block.
        mv.visitLabel(handler);
        mv.visitMethodInsn(INVOKESTATIC, "com/sun/fortress/runtimeSystem/BaseTask", 
                           "leaveTransaction", "(Ljava/lang/Throwable;)V");
        // Wait a randomized exponential amount of time after an error
        mv.visitMethodInsn(INVOKESTATIC, "com/sun/fortress/runtimeSystem/BaseTask",
                           "delayTransaction", "()V");
        mv.visitJumpInsn(GOTO, startOver);

        // Exit
        mv.visitLabel(exit);
    }

    /** An atomic expression over a body that is no do block: the code of the atomic block that
     *  holds the body alone, which is what the parser makes of atomic do e end. */
    public void forAtomicExpr(com.sun.fortress.nodes.AtomicExpr x) {
        Expr body = x.getExpr();
        forAtomicBlock(ExprFactory.makeBlock(NodeUtil.getSpan(x), NodeUtil.getExprType(x), true, true,
                                             Collections.<Expr>singletonList(body)));
    }


    public void forBlock(Block x) {
        if (x.isAtomicBlock()) {
            forAtomicBlock(x);
        } else {
            forBlockHelper(x);
        }
    }

